-- Zumba fitness: nová fotka na přání studia (17. 11. 2026) – skupinka žen různého věku a postavy tančí s rukama nahoře,
-- ve stejném světlém studiu jako fotky ostatních lekcí, v rohu pruh OCTOPUSH / ZUMBA FITNESS. Uložená jako nahraný obrázek.
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data") VALUES
  ('c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2', 'zumba-fitness.webp', 'image/webp', 1600, 900, 104930, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
-- …u lekce místo dosavadní fotky – jen dokud ji studio nevyměnilo za jinou.
UPDATE "class_types" SET "image_url" = '/media/c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2.webp'
WHERE "slug" = 'zumba-fitness' AND "image_url" = '/media/aef42593-3d7b-4d26-a6e6-07ee2d001857.webp'
  AND EXISTS (SELECT 1 FROM "media" WHERE "id" = 'c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2');
--> statement-breakpoint
-- Je vytvořená pomocí AI jako ta dosavadní: dostane stejné označení (vodoznak chobotnice s „AI“), pokud ho měla stará.
UPDATE "settings" SET "value" = (SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT jsonb_array_elements_text("value" || '["/media/c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2.webp"]'::jsonb) x) s)
WHERE "key" = 'aiImages' AND jsonb_typeof("value") = 'array' AND "value" ? '/media/aef42593-3d7b-4d26-a6e6-07ee2d001857.webp' AND NOT "value" ? '/media/c79f4af0-1b0d-4d0c-9f07-dd2cc08a4dc2.webp';
